cat > /app/run.py <<'EOF'
import inspect, numpy as np, mteb

MODEL = "BAAI/bge-small-zh-v1.5"
REV = "7999e1d3359715c523056ef9478215996d62a620"

model = mteb.get_model(MODEL, revision=REV)

docs = [l.rstrip("\n") for l in open("/app/data.txt", encoding="utf-8") if l.strip()]
query = "terminal-bench"

def enc(texts, ptype):
    fn = model.encode
    kw = {}
    try:
        params = inspect.signature(fn).parameters
    except (TypeError, ValueError):
        params = {}
    if "task_name" in params or any(p.kind == p.VAR_KEYWORD for p in params.values()):
        kw["task_name"] = "Retrieval"
    if "prompt_type" in params:
        try:
            from mteb.encoder_interface import PromptType
        except Exception:
            try:
                from mteb import PromptType
            except Exception:
                PromptType = None
        if PromptType is not None:
            kw["prompt_type"] = getattr(PromptType, ptype)
    try:
        return np.asarray(fn(texts, **kw))
    except TypeError:
        kw.pop("prompt_type", None)
        try:
            return np.asarray(fn(texts, **kw))
        except TypeError:
            kw.pop("task_name", None)
            return np.asarray(fn(texts, **kw))

q = enc([query], "query")
d = enc(docs, "passage")
qn = q / np.linalg.norm(q, axis=1, keepdims=True)
dn = d / np.linalg.norm(d, axis=1, keepdims=True)
sims = (dn @ qn[0])
order = np.argsort(-sims)
for r, i in enumerate(order[:8], 1):
    print(r, round(float(sims[i]), 4), docs[i][:80])
res = docs[order[4]]
open("/app/result.txt", "w", encoding="utf-8").write(res + "\n")
print("RESULT:", res)
EOF
cd /app && python3 run.py

